export const LP_IMERSAO_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n__HEAD_META__\n<link rel=\"preconnect\" href=\"https://connect.facebook.net\">\n__PIXEL_BASE__\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&family=JetBrains+Mono:wght@400;500;700&display=swap\" rel=\"stylesheet\">\n<script>window.IM = __IM_DADOS__;</script>\n<script>if(\"scrollRestoration\" in history)history.scrollRestoration=\"manual\";</script>\n<style>\n:root{\n  --bg:#0A0A0A; --bg2:#0E0F11; --panel:rgba(255,255,255,.025);\n  --text:#F5F5F5; --muted:#8A8A8A; --dim:#5C5C5F;\n  --line:rgba(255,255,255,.08); --line2:rgba(255,255,255,.14);\n  --blue:#4458FF; --blue-hi:#6E7DFF; --blue-soft:rgba(68,88,255,.14);\n  --sans:\"Space Grotesk\",system-ui,sans-serif; --mono:\"JetBrains Mono\",ui-monospace,monospace;\n  --w:1200px;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml{scroll-behavior:smooth;background:var(--bg)}\nhtml.lenis,html.lenis body{height:auto}\n.lenis.lenis-smooth{scroll-behavior:auto!important}\nbody{background:var(--bg);color:var(--text);font-family:var(--sans);font-size:18px;line-height:1.55;-webkit-font-smoothing:antialiased;overflow-x:hidden}\na{color:inherit;text-decoration:none}\nimg{display:block;max-width:100%}\n.wrap{max-width:var(--w);margin:0 auto;padding:0 24px}\n\n/* ---------- elementos base ---------- */\n.kicker{font-family:var(--mono);font-size:13px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;color:var(--text);display:inline-flex;align-items:center;gap:12px}\n.kicker::before{content:\"\";width:8px;height:8px;background:var(--blue);box-shadow:0 0 12px var(--blue)}\nh1,h2,h3{font-weight:700;letter-spacing:-.035em;line-height:1.02}\nh2{font-size:clamp(34px,4.3vw,58px);margin-top:20px;max-width:18ch}\nh2.nobr{max-width:none}\n#agente h2.nobr{font-size:clamp(20px,2.5vw,36px);line-height:1.18;letter-spacing:-.02em}\n.lead{color:var(--muted);font-size:clamp(17px,1.4vw,20px);max-width:60ch;margin-top:22px}\n.btn{display:inline-flex;align-items:center;gap:12px;background:var(--text);color:#0A0A0A;font-weight:700;font-size:17px;padding:17px 26px;border-radius:12px;transition:background .25s,color .25s,box-shadow .25s,transform .25s}\n.btn svg{width:18px;height:18px;transition:transform .25s}\n.btn:hover{background:var(--blue);color:#fff;box-shadow:0 0 0 1px var(--blue-hi),0 10px 40px -8px rgba(68,88,255,.7)}\n.btn:hover svg{transform:translateX(3px)}\n.micro{font-family:var(--mono);font-size:13px;color:var(--muted);letter-spacing:.04em;margin-top:16px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:18px}\nsection{position:relative;padding:130px 0}\nsection.alt{background:var(--bg2)}\n.grid-bg::before{content:\"\";position:absolute;inset:0;pointer-events:none;\n  background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);\n  background-size:64px 64px;-webkit-mask-image:radial-gradient(ellipse 70% 60% at 50% 40%,#000 20%,transparent 75%);mask-image:radial-gradient(ellipse 70% 60% at 50% 40%,#000 20%,transparent 75%);opacity:.55}\nsection>.wrap{position:relative}\n.head-c{text-align:center;display:flex;flex-direction:column;align-items:center}\n.head-c h2{max-width:22ch}\n.ico{width:22px;height:22px;stroke-width:1.6}\n\n/* reveal */\n.rv{opacity:0;transform:translateY(24px);transition:opacity .9s cubic-bezier(.2,.7,.2,1),transform .9s cubic-bezier(.2,.7,.2,1)}\n.rv.in{opacity:1;transform:none}\n@media (prefers-reduced-motion:reduce){.rv{opacity:1;transform:none;transition:none}}\n\n/* ---------- nav ---------- */\n.nav{position:fixed;top:16px;left:50%;transform:translateX(-50%);z-index:50;display:flex;align-items:center;gap:6px;padding:7px 7px 7px 18px;border:1px solid var(--line2);border-radius:14px;background:rgba(10,10,10,.62);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);width:max-content;max-width:calc(100% - 24px)}\n.nav .brand{font-family:var(--mono);font-weight:700;font-size:13px;letter-spacing:.12em;margin-right:14px;white-space:nowrap}\n.nav .brand b{color:var(--blue-hi)}\n.nav a.l{font-family:var(--mono);font-size:12.5px;color:var(--muted);padding:8px 12px;border-radius:9px;transition:color .2s,background .2s;white-space:nowrap}\n.nav a.l:hover{color:var(--text);background:rgba(255,255,255,.05)}\n.nav .btn{font-size:13.5px;padding:10px 16px;border-radius:9px;margin-left:8px;white-space:nowrap}\n\n/* ---------- hero ---------- */\n.hero{position:relative;min-height:100vh;min-height:100svh;padding:0;overflow:hidden;background:radial-gradient(ellipse 60% 50% at 62% 45%,rgba(68,88,255,.10),transparent 70%),var(--bg)}\n.hero .hl{position:absolute;inset:0;will-change:transform}\n.hero .hl:nth-of-type(1){z-index:0}.hero .hl:nth-of-type(2){z-index:1}.hero .hl-char{z-index:2}\n#hero3d{position:absolute;inset:0;width:100%;height:100%;display:block}\n.hero .char{position:absolute;right:max(0px,calc(50vw - 735px));bottom:0;height:min(92vh,940px,64vw);width:auto;pointer-events:none;transform:translate3d(var(--mx,0px),var(--my,0px),0);transition:transform .6s cubic-bezier(.2,.7,.2,1)}\n.hero .char-glow{position:absolute;right:calc(50vw - 740px);bottom:8%;width:min(34vw,480px);aspect-ratio:1;pointer-events:none;translate:calc(var(--mx,0px)*-.6) calc(var(--my,0px)*-.6);transition:translate .8s cubic-bezier(.2,.7,.2,1);background:radial-gradient(circle,rgba(68,88,255,.22),transparent 65%);transform:translateX(12%)}\n.hero .fade{position:absolute;left:0;right:0;bottom:0;height:18vh;z-index:2;pointer-events:none;background:linear-gradient(to top,var(--bg),transparent)}\n.hero .fade{z-index:3;height:26vh}\n.hero .cut{display:none}\n.hero .wrap{z-index:4;will-change:transform}\n.hero .wrap{position:relative;z-index:3;min-height:100vh;min-height:100svh;display:flex;flex-direction:column;justify-content:center;padding-top:110px;padding-bottom:80px}\n.status{display:inline-flex;align-items:center;gap:10px;font-family:var(--mono);font-size:12px;font-weight:700;letter-spacing:.16em;color:var(--blue-hi);border:1px solid rgba(68,88,255,.35);background:rgba(68,88,255,.08);padding:7px 12px;border-radius:8px;width:max-content}\n.status i{width:8px;height:8px;border-radius:50%;background:var(--blue-hi);box-shadow:0 0 0 0 rgba(110,125,255,.7);animation:pulse 1.8s infinite}\n@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(110,125,255,.7)}70%{box-shadow:0 0 0 10px rgba(110,125,255,0)}100%{box-shadow:0 0 0 0 rgba(110,125,255,0)}}\n.hero .kicker{margin-top:28px;font-size:12.5px;max-width:44ch;line-height:1.6}\n.hero h1{font-size:clamp(46px,6.4vw,96px);margin-top:18px;max-width:11ch;text-shadow:0 2px 40px rgba(10,10,10,.8)}\n.hero .lead{max-width:40ch;color:#A6A6AA}\n.hero .cta{margin-top:38px}\n\n/* ---------- problema ---------- */\n.compare{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:64px}\n.col{padding:30px}\n.col h3{font-family:var(--mono);font-size:13px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;display:flex;align-items:center;gap:10px}\n.col ul{list-style:none;margin-top:22px}\n.col li{display:flex;gap:14px;padding:16px 0;border-top:1px solid var(--line);font-size:17.5px;align-items:flex-start}\n.col li svg{flex:none;width:20px;height:20px;margin-top:3px}\n.col.bot{color:var(--muted)}\n.col.bot li svg{color:var(--dim)}\n.col.ag{border-color:rgba(68,88,255,.35);background:linear-gradient(180deg,rgba(68,88,255,.08),rgba(68,88,255,.015))}\n.col.ag h3{color:var(--blue-hi)}\n.col.ag li svg{color:var(--blue-hi)}\n.remate{margin-top:56px;font-size:clamp(22px,2.3vw,32px);font-weight:500;letter-spacing:-.02em;line-height:1.3}\n.remate em{font-style:normal;color:var(--muted)}\n\n/* ---------- formato ---------- */\n.fmt{display:grid;grid-template-columns:1.15fr .85fr;gap:48px;align-items:end}\n.fmt-item{display:flex;gap:16px;align-items:center;padding:24px 26px}\n.fmt-item .ic{flex:none;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--blue-soft);color:var(--blue-hi);border:1px solid rgba(68,88,255,.3)}\n.fmt-item p{font-size:17px}\n.ponte{margin-top:72px;font-family:var(--mono);font-size:14px;letter-spacing:.06em;color:var(--muted);display:flex;align-items:center;gap:12px}\n.ponte svg{color:var(--blue-hi);width:18px;height:18px}\n\n/* ---------- autoridade ---------- */\n.auth{display:grid;grid-template-columns:.8fr 1.2fr;gap:64px;align-items:center}\n.photo{position:relative;border-radius:22px;overflow:hidden;border:1px solid var(--line2);box-shadow:0 40px 90px -30px rgba(0,0,0,.9)}\n.photo img{width:100%;aspect-ratio:527/680;object-fit:cover;object-position:top}\n.photo figcaption{position:absolute;left:14px;right:14px;bottom:14px;display:flex;justify-content:space-between;align-items:center;font-family:var(--mono);font-size:12px;letter-spacing:.08em;padding:11px 14px;border-radius:10px;background:rgba(10,10,10,.72);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);border:1px solid var(--line2)}\n.photo figcaption span:last-child{color:var(--muted)}\n.auth h2{font-size:clamp(26px,2.7vw,38px);max-width:none;line-height:1.14;letter-spacing:-.025em}\n.pills{display:flex;flex-wrap:wrap;gap:10px;margin-top:30px}\n.pills span{font-family:var(--mono);font-size:12.5px;padding:9px 13px;border:1px solid var(--line2);border-radius:9px;color:#C9C9CC;background:var(--panel)}\n\n/* ---------- currículo ---------- */\n.cur{display:grid;grid-template-columns:1fr 1fr;gap:56px;margin-top:72px;align-items:start}\n.days{display:flex;flex-direction:column;gap:14px}\n.day{padding:28px;transition:border-color .4s,background .4s,transform .4s}\n.day .top{display:flex;align-items:center;justify-content:space-between}\n.day .n{font-family:var(--mono);font-size:12.5px;font-weight:700;letter-spacing:.16em;color:var(--dim);transition:color .4s}\n.day .top svg{color:var(--dim);transition:color .4s}\n.day h3{font-size:25px;letter-spacing:-.02em;margin-top:16px;line-height:1.15}\n.day p{color:var(--muted);margin-top:10px;font-size:16.5px}\n.day.on{border-color:rgba(68,88,255,.45);background:linear-gradient(135deg,rgba(68,88,255,.1),rgba(68,88,255,.01) 60%)}\n.day.on .n,.day.on .top svg{color:var(--blue-hi)}\n\n/* ---------- works wheel (mapa da semana) ---------- */\n.ww{position:relative;height:min(840px,calc(100vh - 110px));min-height:560px;margin-top:56px;overflow:hidden;border:1px solid var(--line);border-radius:24px;background:radial-gradient(ellipse 60% 70% at 50% 50%,rgba(68,88,255,.10),transparent 70%),#08090B;user-select:none;-webkit-user-select:none}\n.ww-stage{position:absolute;inset:0;cursor:grab;outline:none;touch-action:pan-x}\n.ww-stage:active{cursor:grabbing}\n.ww-stage:focus-visible{outline:2px solid var(--blue-hi);outline-offset:-6px}\n.ww-wheel{position:absolute;left:50%;top:50%;transform-style:preserve-3d}\n.ww-card{position:absolute;backface-visibility:hidden;-webkit-backface-visibility:hidden}\n.ww-face{display:flex;flex-direction:column;justify-content:space-between;width:100%;height:100%;padding:calc(var(--ch,300px)*.1);border-radius:16px;background:linear-gradient(160deg,#16181f,#0b0c0f 70%);border:1px solid var(--line2);box-shadow:0 30px 70px -30px rgba(0,0,0,.95);transition:border-color .4s,background .4s}\n.ww-card.on .ww-face{border-color:rgba(110,125,255,.6);background:linear-gradient(160deg,rgba(68,88,255,.22),#0b0c0f 65%);box-shadow:0 30px 80px -30px rgba(68,88,255,.45)}\n.ww-top{display:flex;justify-content:space-between;align-items:center;font-family:var(--mono);font-weight:700;font-size:calc(var(--ch,300px)*.05);letter-spacing:.16em;color:var(--dim)}\n.ww-top svg{width:calc(var(--ch,300px)*.085);height:calc(var(--ch,300px)*.085)}\n.ww-card.on .ww-top{color:var(--blue-hi)}\n.ww-face h3{font-size:calc(var(--ch,300px)*.105);letter-spacing:-.025em;line-height:1.08}\n.ww-face p{color:var(--muted);font-size:calc(var(--ch,300px)*.056);line-height:1.45;margin-top:calc(var(--ch,300px)*.04)}\n.ww-label,.ww-title{position:absolute;pointer-events:none;font-weight:700;letter-spacing:-.03em;line-height:1}\n.ww-label{inset:0;display:grid;place-items:center;color:var(--text)}\n.ww-title{left:6%;top:50%;transform:translateY(-50%);opacity:0;color:var(--text)}\n.ww-index{position:absolute;top:7%;right:3%;list-style:none;text-align:right;font-family:var(--mono);line-height:2}\n.ww-index button{all:unset;cursor:pointer;color:var(--dim);transition:color .25s}\n.ww-index button:hover{color:var(--muted)}\n.ww-index button.on{color:var(--text)}\n.ww-index button.on::before{content:\"\";display:inline-block;width:7px;height:7px;margin-right:10px;background:var(--blue);box-shadow:0 0 10px var(--blue);vertical-align:middle}\n.ww-hint{position:absolute;left:50%;bottom:22px;transform:translateX(-50%);color:var(--dim);animation:hint 1.8s ease-in-out infinite;transition:opacity .4s}\n.ww-hint svg{width:22px;height:22px}\n@keyframes hint{50%{transform:translate(-50%,5px)}}\n.days-mob{display:none;margin-top:40px}\n@media (max-width:900px),(pointer:coarse){.ww{display:none}.days-mob{display:flex}}\n\n/* ---------- casos ---------- */\n.cases{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:64px}\n.case{padding:34px;position:relative;overflow:hidden}\n.case::after{content:\"\";position:absolute;inset:auto -40% -60% auto;width:70%;aspect-ratio:1;background:radial-gradient(circle,rgba(68,88,255,.16),transparent 65%);opacity:0;transition:opacity .5s}\n.case:hover::after{opacity:1}\n.case .ic{width:48px;height:48px;border-radius:12px;display:grid;place-items:center;border:1px solid var(--line2);color:var(--blue-hi);background:rgba(255,255,255,.02)}\n.case h3{font-size:26px;letter-spacing:-.02em;margin-top:26px;line-height:1.15}\n.case p{color:var(--muted);margin-top:12px;font-size:16.5px}\n.case .lbl{position:absolute;right:26px;top:30px;font-family:var(--mono);font-size:11.5px;letter-spacing:.14em;color:var(--dim)}\n\n/* ---------- provas ---------- */\n.prints{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:64px;align-items:center;max-width:1040px;margin-left:auto;margin-right:auto}\n.print{padding:10px;border-radius:22px}\n.print img{border-radius:14px;width:100%}\n\n/* ---------- investimento ---------- */\n.offer{max-width:820px;margin:0 auto;padding:64px 56px;text-align:center;border-color:rgba(68,88,255,.3);background:radial-gradient(ellipse 80% 60% at 50% 0%,rgba(68,88,255,.12),transparent 70%),var(--panel);display:flex;flex-direction:column;align-items:center}\n.offer h2{max-width:20ch;font-size:clamp(30px,3.6vw,48px)}\n.price{font-size:clamp(88px,11vw,150px);font-weight:700;letter-spacing:-.06em;line-height:1;margin-top:40px}\n.price small{font-size:.32em;letter-spacing:-.02em;vertical-align:.95em;margin-right:6px;color:var(--muted)}\n.incl{font-family:var(--mono);font-size:13.5px;color:#C9C9CC;margin-top:18px;letter-spacing:.03em}\n.obj{color:var(--muted);max-width:52ch;margin:34px auto 0;font-size:17.5px}\n.offer .btn{margin-top:38px}\n\n/* ---------- faq ---------- */\n.faq{max-width:860px;margin:64px auto 0}\n.faq details{border-top:1px solid var(--line)}\n.faq details:last-child{border-bottom:1px solid var(--line)}\n.faq summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:24px;padding:26px 4px;font-size:21px;font-weight:500;letter-spacing:-.015em}\n.faq summary::-webkit-details-marker{display:none}\n.faq summary svg{flex:none;width:20px;height:20px;color:var(--muted);transition:transform .3s,color .3s}\n.faq details[open] summary svg{transform:rotate(45deg);color:var(--blue-hi)}\n.faq details p{color:var(--muted);padding:0 4px 28px;max-width:66ch;font-size:17px}\n\n/* ---------- footer ---------- */\n.final{padding:150px 0 0;overflow:hidden}\n.final>.wrap{display:flex;flex-direction:column;align-items:center;text-align:center}\n.final h2{max-width:16ch;font-size:clamp(40px,5.4vw,78px);margin-left:auto;margin-right:auto}\n.final .micro{font-size:14px}\n.final .btn{margin-top:36px}\n.lower{margin-top:130px;border-top:1px solid var(--line);padding:26px 0 30px}\n.lower .wrap{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}\n.lt{display:flex;align-items:center;gap:14px}\n.lt .bar{width:3px;height:40px;background:var(--blue);box-shadow:0 0 14px var(--blue)}\n.lt b{display:block;font-size:17px;letter-spacing:-.01em}\n.lt span{display:block;font-family:var(--mono);font-size:12px;color:var(--muted);letter-spacing:.06em}\n.lower .legal{font-family:var(--mono);font-size:12px;line-height:1.9;color:var(--muted);text-align:right;letter-spacing:.02em}\n.lower .legal a{color:#C9C9CC;text-decoration:underline;text-decoration-color:rgba(255,255,255,.25);text-underline-offset:3px}\n.lower .legal a:hover{color:var(--text)}\n@media (max-width:900px){.lower .legal{text-align:left}}\n\n/* ---------- responsivo ---------- */\n@media (max-width:1100px){\n  .nav a.l{display:none}\n}\n@media (max-width:900px){\n  section{padding:96px 0}\n  .compare,.cases,.prints,.fmt,.auth,.cur{grid-template-columns:1fr}\n  .fmt{gap:28px}\n  .auth{gap:36px}\n  .photo{max-width:420px}\n  .cur{gap:22px;margin-top:48px}\n}\n@media (max-width:640px){\n  body{font-size:17px}\n  .nav{padding-left:14px}\n  .nav .brand{margin-right:4px}\n  /* celular: personagem inteira em cima (cabeça à cintura), texto embaixo */\n  .hero .char{top:62px;bottom:auto;height:calc((44svh - 62px) / .54);right:-14px;opacity:1}\n  .hero .char-glow{right:-20px;top:70px;bottom:auto;width:80vw}\n  .hero .cut{display:block;position:absolute;left:0;right:0;top:calc(44svh - 70px);bottom:0;z-index:3;pointer-events:none;background:linear-gradient(to bottom,rgba(10,10,10,0),rgba(10,10,10,.97) 70px,rgba(10,10,10,.97))}\n  .hero .wrap{justify-content:flex-start;padding-top:calc(44svh - 6px);padding-bottom:40px}\n  .hero .kicker{margin-top:18px}\n  .hero h1{font-size:42px;margin-top:14px}\n  .hero .lead{margin-top:16px;font-size:16px}\n  .hero .cta{margin-top:24px}\n  .btn{font-size:15.5px;padding:16px 20px}\n  .hero h1{max-width:9ch}\n  .col,.case{padding:24px}\n  .offer{padding:48px 22px}\n  .faq summary{font-size:18px}\n  .btn{width:100%;justify-content:center}\n}\n\n.lotes{list-style:none;margin:18px auto 6px;padding:0;max-width:420px;display:grid;gap:8px}\n.lotes li{display:flex;justify-content:space-between;gap:12px;padding:10px 14px;border:1px solid rgba(255,255,255,.12);border-radius:10px;font-size:14px;color:#9aa0b4}\n.lotes li.on{color:#fff;border-color:#6c63ff;background:rgba(108,99,255,.12)}\n.lotes li b{font-weight:700}\n/* oferta: de/por, lote, escassez, certificado, garantia */\n.de{font-family:var(--mono);font-size:17px;color:var(--muted);margin-top:36px;letter-spacing:.02em}\n.de s{text-decoration-thickness:2px;text-decoration-color:rgba(255,110,110,.85)}\n.de+.price{margin-top:4px}\n.lote-tag{margin-top:16px;font-family:var(--mono);font-size:12.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--blue-hi)}\n.escassez{width:100%;max-width:420px;margin:18px auto 4px}\n.escassez .tx{display:flex;justify-content:space-between;gap:12px;font-family:var(--mono);font-size:12.5px;color:#C9C9CC;letter-spacing:.04em}\n.escassez .trilho{height:10px;border-radius:99px;background:rgba(255,255,255,.06);border:1px solid var(--line);overflow:hidden;margin-top:8px}\n.escassez .enchido{height:100%;width:0;border-radius:99px;background:linear-gradient(90deg,var(--blue),var(--blue-hi));box-shadow:0 0 14px var(--blue);transition:width 1.2s cubic-bezier(.2,.7,.2,1)}\n.incl.cert{margin-top:10px}\n.incl.cert svg{display:inline-block;width:16px;height:16px;margin-right:8px;vertical-align:-3px;color:var(--blue-hi)}\n.garantia{display:flex;gap:14px;align-items:center;margin-top:30px;padding:14px 18px;border:1px solid rgba(68,88,255,.35);border-radius:14px;background:var(--blue-soft);text-align:left;max-width:460px}\n.garantia svg{flex:none;width:30px;height:30px;color:var(--blue-hi)}\n.garantia b{display:block;font-size:16px;letter-spacing:-.01em}\n.garantia span{display:block;font-size:14px;color:var(--muted);line-height:1.45;margin-top:2px}\n/* depoimento */\n.depo{max-width:900px;margin:56px auto 0;padding:10px;border-radius:22px}\n.depo video{display:block;width:100%;height:auto;aspect-ratio:16/9;border-radius:14px;background:#000}\n.depo figcaption{font-family:var(--mono);font-size:12.5px;color:var(--muted);letter-spacing:.06em;padding:14px 8px 6px}\n/* pré-checkout */\n.pc{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;padding:16px;background:rgba(5,5,8,.8);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}\n.pc[hidden]{display:none}\n.pc-box{position:relative;width:100%;max-width:440px;max-height:calc(100svh - 32px);overflow:auto;padding:34px 28px 24px;border-radius:20px;border:1px solid rgba(68,88,255,.35);background:var(--bg2);box-shadow:0 30px 80px -20px rgba(68,88,255,.35)}\n.pc-box h3{font-size:25px;letter-spacing:-.02em;line-height:1.15;margin-top:16px}\n.pc-box .s{color:var(--muted);font-size:15px;margin-top:8px}\n.pc-box label{display:block;margin-top:16px;font-family:var(--mono);font-size:11.5px;letter-spacing:.1em;text-transform:uppercase;color:#C9C9CC}\n.pc-box input{display:block;width:100%;margin-top:6px;padding:14px;border-radius:12px;border:1px solid var(--line2);background:rgba(255,255,255,.03);color:var(--text);font:inherit;font-size:16px}\n.pc-box input:focus{outline:none;border-color:var(--blue);box-shadow:0 0 0 3px rgba(68,88,255,.25)}\n.pc-box .btn{width:100%;justify-content:center;margin-top:22px;border:0;cursor:pointer;font-family:inherit}\n.pc-box .btn[disabled]{opacity:.7;cursor:wait}\n.pc-err{color:#FF8A8A;font-size:14px;margin-top:12px;min-height:1px}\n.pc-box .lgpd{font-size:12.5px;color:var(--muted);margin-top:14px;line-height:1.5}\n.pc-box .lgpd a{color:#C9C9CC;text-decoration:underline;text-underline-offset:3px}\n.pc-x{position:absolute;top:12px;right:12px;width:36px;height:36px;display:grid;place-items:center;border:0;border-radius:10px;background:transparent;color:var(--muted);cursor:pointer}\n.pc-x:hover{color:var(--text);background:rgba(255,255,255,.06)}\n.pc-x svg{width:20px;height:20px}\n@media (max-width:640px){.offer .garantia{padding:12px 14px}.pc-box{padding:30px 20px 20px}}\n.hero h1 .evt{display:block}\n.hero h1 .sub{display:block;white-space:nowrap;font-size:clamp(19px,2.7vw,38px);font-weight:600;letter-spacing:-.01em;line-height:1.1;margin-top:18px;color:var(--blue-hi);text-shadow:none}\n</style>\n<script type=\"importmap\">\n{\"imports\":{\n  \"three\":\"https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js\",\n  \"three/addons/\":\"https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/\"\n}}\n</script>\n</head>\n<body>\n\n<nav class=\"nav\" aria-label=\"Navegação\">\n  <span class=\"brand\">HERMES<b>/</b>IMERSÃO</span>\n  <a class=\"l\" href=\"#formato\">Como funciona</a>\n  <a class=\"l\" href=\"#curriculo\">As duas noites</a>\n  <a class=\"l\" href=\"#provas\">Provas</a>\n  <a class=\"l\" href=\"#investimento\">Investimento</a>\n  <a class=\"l\" href=\"#faq\">FAQ</a>\n  <a class=\"btn\" href=\"#investimento\">Quero minha vaga</a>\n</nav>\n\n<!-- ============ HERO ============ -->\n<header class=\"hero\" data-parallax-layers>\n  <div class=\"hl\" data-parallax-layer=\"1\" aria-hidden=\"true\"><canvas id=\"hero3d\"></canvas></div>\n  <div class=\"hl\" data-parallax-layer=\"2\" aria-hidden=\"true\"><div class=\"char-glow\"></div></div>\n  <div class=\"hl hl-char\" data-parallax-layer=\"4\" aria-hidden=\"true\"><picture><source type=\"image/webp\" srcset=\"/imersao/hermes-personagem.webp\"><img class=\"char\" src=\"/imersao/hermes-personagem.png?v=5\" alt=\"\" fetchpriority=\"high\" decoding=\"async\"></picture></div>\n  <div class=\"fade\" aria-hidden=\"true\"></div>\n  <div class=\"cut\" aria-hidden=\"true\"></div>\n  <div class=\"wrap\" data-parallax-layer=\"3\">\n    <span class=\"status\"><i></i>SEU HERMES: ONLINE</span>\n    <span class=\"kicker\">Duas noites ao vivo. Um agente com ferramentas, memórias e um servidor só dele.</span>\n    <h1><span class=\"evt\">Imersão Arquiteto de Agentes</span><span class=\"sub\">Seu time de IA que não dorme.</span></h1>\n    <p class=\"lead\">No dia 1, a gente instala o Hermes e eu te mostro tudo o que ele faz. E no dia 2, o seu Hermes vai para um servidor onde você vai montar seus squads de agentes que trabalham juntos.</p>\n    <div class=\"cta\">\n      <a class=\"btn\" href=\"#investimento\">Quero minha vaga na Imersão <i data-lucide=\"arrow-right\"></i></a>\n      <p class=\"micro\"><span data-im=\"preco\">R$ 44</span> · 2 noites ao vivo · <span data-im=\"noites\">25 e 26/11</span>, às 19h</p>\n    </div>\n  </div>\n</header>\n\n<!-- ============ PROBLEMA ============ -->\n<section class=\"grid-bg\" id=\"problema\">\n  <div class=\"wrap\">\n    <span class=\"kicker rv\">Você já usa IA. Só não tem um time trabalhando para você.</span>\n    <h2 class=\"rv nobr\">Sua IA só te responde...<br>E para por aí.</h2>\n    <p class=\"lead rv\">Um software só faz o que ele está programado pra fazer. Um chatbot te devolve um output pra cada input que você dá pra ele. E nos dois casos o gargalo é você. Nos dois casos o start só acontece quando você está lá.</p>\n\n    <div class=\"compare\">\n      <div class=\"col card bot rv\">\n        <h3><i data-lucide=\"message-square\" class=\"ico\"></i>Chatbot</h3>\n        <ul>\n          <li><i data-lucide=\"x\"></i>Se perde no contexto e na memória</li>\n          <li><i data-lucide=\"x\"></i>Você inicia toda conversa</li>\n          <li><i data-lucide=\"x\"></i>Só responde texto</li>\n          <li><i data-lucide=\"x\"></i>Você decide cada passo</li>\n        </ul>\n      </div>\n      <div class=\"col card ag rv\">\n        <h3><i data-lucide=\"bot\" class=\"ico\"></i>Agente Hermes</h3>\n        <ul>\n          <li><i data-lucide=\"check\"></i>Guarda memória em 4 camadas sobre você</li>\n          <li><i data-lucide=\"check\"></i>Ele age sozinho, no horário que você marcou</li>\n          <li><i data-lucide=\"check\"></i>Tem mãos: mexe em arquivo, navega, clica, preenche</li>\n          <li><i data-lucide=\"check\"></i>Ele decide o caminho e se autocorrige no meio</li>\n        </ul>\n      </div>\n    </div>\n\n    <p class=\"remate rv\">Hermes não é mais um chat pra você abrir.<br><em>É um agente que já chega pronto.<br>Ele só precisa te conhecer.</em></p>\n  </div>\n</section>\n\n<!-- ============ FORMATO ============ -->\n<section class=\"alt\" id=\"formato\">\n  <div class=\"wrap\">\n    <div class=\"fmt\">\n      <div>\n        <span class=\"kicker rv\">Como funciona a Imersão</span>\n        <h2 class=\"rv\">No dia 1, a gente instala o Hermes no seu computador. No dia 2, ele vai morar na VPS.</h2>\n        <p class=\"lead rv\">Duas noites ao vivo, das 19h às 22h. Na noite 1 nós instalamos o Hermes e você aprende o que o Hermes faz de verdade: navega sozinho, enxerga a sua tela e roda tarefas agendadas. Na noite 2 a gente compra, instala e blinda uma VPS do zero, e deixa um Squad de Agentes de Marketing rodando de forma orquestrada.</p>\n      </div>\n      <div class=\"fmt-item card rv\">\n        <span class=\"ic\"><i data-lucide=\"messages-square\" class=\"ico\"></i></span>\n        <p>Grupo da turma pra tirar dúvidas direto com o RedPro</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ AUTORIDADE ============ -->\n<section class=\"grid-bg\" id=\"redpro\">\n  <div class=\"wrap auth\">\n    <figure class=\"photo rv\">\n      <img src=\"/imersao/redpro.jpg\" alt=\"RedPro, instrutor da Imersão Arquiteto de Agentes\" loading=\"lazy\">\n      <figcaption><span>RedPro</span><span>@redpro.ia</span></figcaption>\n    </figure>\n    <div>\n      <span class=\"kicker rv\">Sobre o RedPro</span>\n      <h2 class=\"rv\">Engenheiro, +10 anos sustentando sistemas críticos no governo federal, especialista em IA para negócios e arquiteto de Soluções Agênticas.</h2>\n      <p class=\"lead rv\">Nos últimos anos, migrei de infraestrutura crítica de TI pra soluções agênticas, porque toda a experiência de manter sistemas no ar, lidar com equipes de dev e de segurança, é exatamente o que faz diferença quando o assunto é colocar Agentes de IA pra trabalhar de forma segura e sustentável.</p>\n      <div class=\"pills rv\">\n        <span>Engenheiro de Telecomunicações</span>\n        <span>+10 anos em infra crítica</span>\n        <span>MBA em IA para negócios</span>\n        <span>Especialista em Soluções Agênticas</span>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ CURRÍCULO ============ -->\n<section class=\"alt\" id=\"curriculo\">\n  <div class=\"wrap\">\n    <div class=\"head-c\">\n      <span class=\"kicker rv\">O mapa das duas noites</span>\n      <h2 class=\"rv\">O que a gente faz em cada noite.</h2>\n    </div>\n    <div class=\"ww rv\" id=\"ww\">\n      <div class=\"ww-stage\" tabindex=\"0\" role=\"listbox\" aria-label=\"O mapa das duas noites\" data-lenis-prevent>\n        <div class=\"ww-wheel\">\n          <div class=\"ww-card\" role=\"option\" id=\"ww-0\" aria-label=\"Noite 1 · instalação\"><div class=\"ww-face\">\n            <div class=\"ww-top\"><span>NOITE 1 · INSTALAÇÃO</span><i data-lucide=\"monitor-down\"></i></div>\n            <div><h3>Instalação, interface e cérebro</h3><p>Hermes rodando no seu desktop e no celular, com a personalidade que você escolher e memória sobre você. Você define o modelo de cada tarefa e o que ele pode e não pode acessar.</p></div>\n          </div></div>\n          <div class=\"ww-card\" role=\"option\" id=\"ww-1\" aria-label=\"Noite 1 · navegação\"><div class=\"ww-face\">\n            <div class=\"ww-top\"><span>NOITE 1 · NAVEGAÇÃO</span><i data-lucide=\"mouse-pointer-click\"></i></div>\n            <div><h3>Navegação autônoma</h3><p>Você vê o Hermes abrir o navegador sozinho, clicar, preencher formulário e voltar com o resultado.</p></div>\n          </div></div>\n          <div class=\"ww-card\" role=\"option\" id=\"ww-2\" aria-label=\"Noite 1 · automação\"><div class=\"ww-face\">\n            <div class=\"ww-top\"><span>NOITE 1 · AUTOMAÇÃO</span><i data-lucide=\"calendar-clock\"></i></div>\n            <div><h3>MCP, HUD e tarefas agendadas</h3><p>Ele passa a enxergar a sua tela, falar com as suas outras ferramentas e trabalhar sozinho nos horários que você programar.</p></div>\n          </div></div>\n          <div class=\"ww-card\" role=\"option\" id=\"ww-3\" aria-label=\"Noite 2 · VPS\"><div class=\"ww-face\">\n            <div class=\"ww-top\"><span>NOITE 2 · VPS</span><i data-lucide=\"server\"></i></div>\n            <div><h3>Seu Hermes na VPS</h3><p>Ele sai do seu computador e vai morar num servidor só dele, ligado o tempo todo, mesmo com você offline. A gente monta o seu ao vivo.</p></div>\n          </div></div>\n          <div class=\"ww-card\" role=\"option\" id=\"ww-4\" aria-label=\"Noite 2 · custo\"><div class=\"ww-face\">\n            <div class=\"ww-top\"><span>NOITE 2 · CUSTO</span><i data-lucide=\"wallet\"></i></div>\n            <div><h3>Custo</h3><p>Quanto custa rodar o seu agente por mês, como escolher o plano que cabe no seu bolso.</p></div>\n          </div></div>\n          <div class=\"ww-card\" role=\"option\" id=\"ww-5\" aria-label=\"Noite 2 · segurança\"><div class=\"ww-face\">\n            <div class=\"ww-top\"><span>NOITE 2 · SEGURANÇA</span><i data-lucide=\"shield-check\"></i></div>\n            <div><h3>Segurança da VPS</h3><p>Como controlar quem fala com ele e o que ele faz sozinho.</p></div>\n          </div></div>\n          <div class=\"ww-card\" role=\"option\" id=\"ww-6\" aria-label=\"Noite 2 · squad\"><div class=\"ww-face\">\n            <div class=\"ww-top\"><span>NOITE 2 · SQUAD</span><i data-lucide=\"users\"></i></div>\n            <div><h3>Um time de Marketing trabalhando junto</h3><p>Um coordenador e três especialistas dividindo o trabalho entre si. Você monta o seu primeiro squad ao vivo.</p></div>\n          </div></div>\n        </div>\n      </div>\n      <div class=\"ww-label\" aria-hidden=\"true\">Imersão</div>\n      <div class=\"ww-title\" aria-hidden=\"true\"></div>\n      <ol class=\"ww-index\"><li><button type=\"button\" data-i=\"0\">Instalação</button></li><li><button type=\"button\" data-i=\"1\">Navegação</button></li><li><button type=\"button\" data-i=\"2\">Automação</button></li><li><button type=\"button\" data-i=\"3\">VPS</button></li><li><button type=\"button\" data-i=\"4\">Custo</button></li><li><button type=\"button\" data-i=\"5\">Segurança</button></li><li><button type=\"button\" data-i=\"6\">Marketing</button></li></ol>\n      <span class=\"ww-hint\" aria-hidden=\"true\"><i data-lucide=\"mouse\"></i></span>\n    </div>\n    <div class=\"days days-mob\">\n        <article class=\"day card\"><div class=\"top\"><span class=\"n\">NOITE 1 · INSTALAÇÃO</span><i data-lucide=\"monitor-down\" class=\"ico\"></i></div><h3>Instalação, interface e cérebro</h3><p>Hermes rodando no seu desktop e no celular, com a personalidade que você escolher e memória sobre você. Você define o modelo de cada tarefa e o que ele pode e não pode acessar.</p></article>\n        <article class=\"day card\"><div class=\"top\"><span class=\"n\">NOITE 1 · NAVEGAÇÃO</span><i data-lucide=\"mouse-pointer-click\" class=\"ico\"></i></div><h3>Navegação autônoma</h3><p>Você vê o Hermes abrir o navegador sozinho, clicar, preencher formulário e voltar com o resultado.</p></article>\n        <article class=\"day card\"><div class=\"top\"><span class=\"n\">NOITE 1 · AUTOMAÇÃO</span><i data-lucide=\"calendar-clock\" class=\"ico\"></i></div><h3>MCP, HUD e tarefas agendadas</h3><p>Ele passa a enxergar a sua tela, falar com as suas outras ferramentas e trabalhar sozinho nos horários que você programar.</p></article>\n        <article class=\"day card\"><div class=\"top\"><span class=\"n\">NOITE 2 · VPS</span><i data-lucide=\"server\" class=\"ico\"></i></div><h3>Seu Hermes na VPS</h3><p>Ele sai do seu computador e vai morar num servidor só dele, ligado o tempo todo, mesmo com você offline. A gente monta o seu ao vivo.</p></article>\n        <article class=\"day card\"><div class=\"top\"><span class=\"n\">NOITE 2 · CUSTO</span><i data-lucide=\"wallet\" class=\"ico\"></i></div><h3>Custo</h3><p>Quanto custa rodar o seu agente por mês, como escolher o plano que cabe no seu bolso.</p></article>\n        <article class=\"day card\"><div class=\"top\"><span class=\"n\">NOITE 2 · SEGURANÇA</span><i data-lucide=\"shield-check\" class=\"ico\"></i></div><h3>Segurança da VPS</h3><p>Como controlar quem fala com ele e o que ele faz sozinho.</p></article>\n        <article class=\"day card\"><div class=\"top\"><span class=\"n\">NOITE 2 · SQUAD</span><i data-lucide=\"users\" class=\"ico\"></i></div><h3>Um time de Marketing trabalhando junto</h3><p>Um coordenador e três especialistas dividindo o trabalho entre si. Você monta o seu primeiro squad ao vivo.</p></article>\n    </div>\n  </div>\n</section>\n\n<!-- ============ AGENTE VIVO ============ -->\n<section class=\"grid-bg\" id=\"agente\">\n  <div class=\"wrap\">\n    <span class=\"kicker rv\">Isso acontece ao vivo</span>\n    <h2 class=\"rv nobr\">Duas noites com a tela aberta. Você vê o Hermes trabalhando em tempo real, com o que der certo e com o que der errado.</h2>\n    <div class=\"cases\">\n      <article class=\"case card rv\"><span class=\"lbl\">01</span><span class=\"ic\"><i data-lucide=\"table-2\" class=\"ico\"></i></span><h3>Você vê o Hermes trabalhando</h3><p>Pedidos reais, feitos ao vivo na sua frente, com o que der certo e com o que der errado.</p></article>\n      <article class=\"case card rv\"><span class=\"lbl\">02</span><span class=\"ic\"><i data-lucide=\"scan-eye\" class=\"ico\"></i></span><h3>Ele enxerga o que você enxerga</h3><p>Um gráfico, uma tabela, uma janela aberta: o Hermes lê o que está na tela e responde em cima disso. Você pergunta, ele interpreta, como um copiloto de trabalho.</p></article>\n      <article class=\"case card rv\"><span class=\"lbl\">03</span><span class=\"ic\"><i data-lucide=\"route\" class=\"ico\"></i></span><h3>Ele trava, muda de rota e segue</h3><p>Site sem API, link quebrado, página que não colabora. Você aprende a fazer o Hermes, quando errar, procurar outro caminho por conta própria e entregar o resultado.</p></article>\n      <article class=\"case card rv\"><span class=\"lbl\">04</span><span class=\"ic\"><i data-lucide=\"plug\" class=\"ico\"></i></span><h3>Ele usa as ferramentas que você já tem</h3><p>Conectado às suas ferramentas, o Hermes consulta e age nelas a partir de um único pedido. Também dá para deixar uma tarefa marcada para rodar sozinha no horário que você escolher.</p></article>\n    </div>\n  </div>\n</section>\n\n<!-- ============ PROVAS ============ -->\n<section class=\"alt\" id=\"provas\">\n  <div class=\"wrap\">\n    <div class=\"head-c\">\n      <span class=\"kicker rv\">Mensagem de quem fez</span>\n      <h2 class=\"rv\">Prints, direto das conversas</h2>\n    </div>\n    <div class=\"prints\">\n      <figure class=\"print card rv\"><img src=\"/imersao/print-01.png\" alt=\"Conversa de WhatsApp: aluno conta que já está escrevendo o terceiro plugin e está ansioso pela navegação autônoma\" loading=\"lazy\"></figure>\n      <figure class=\"print card rv\"><img src=\"/imersao/print-02.png\" alt=\"Conversa de WhatsApp: aluno agradece o conteúdo e conta que a esposa passou a usar o Hermes para controlar as contas da casa\" loading=\"lazy\"></figure>\n    </div>\n  </div>\n</section>\n\n<!-- ============ DEPOIMENTO ============ -->\n<section class=\"grid-bg\" id=\"depoimento\">\n  <div class=\"wrap\">\n    <div class=\"head-c\">\n      <span class=\"kicker rv\">Depoimento</span>\n      <h2 class=\"rv\">Quem já monta agentes comigo</h2>\n    </div>\n    <figure class=\"depo card rv\">\n      <video controls playsinline preload=\"none\" poster=\"/imersao/depoimento-neto.jpg\" width=\"1280\" height=\"720\">\n        <source src=\"/imersao/depoimento-neto.mp4\" type=\"video/mp4\">\n      </video>\n      <figcaption>Neto Lima, mentorado do RedPro</figcaption>\n    </figure>\n  </div>\n</section>\n\n<!-- ============ INVESTIMENTO ============ -->\n<section class=\"grid-bg\" id=\"investimento\">\n  <div class=\"wrap\">\n    <div class=\"offer card rv\">\n      <span class=\"kicker\">O investimento</span>\n      <h2>O preço de duas noites que vão mudar como você trabalha daqui pra frente</h2>\n      <p class=\"de\" id=\"im-de\" hidden>de <s data-im=\"de\">R$ 62</s> por</p>\n      <div class=\"price\"><small>R$</small><span data-im=\"precoNum\">44</span></div>\n      <p class=\"lote-tag\" id=\"im-lote-tag\" hidden></p>\n      <div class=\"escassez\" id=\"im-escassez\" hidden>\n        <div class=\"tx\"><span><b id=\"im-pct\">0</b>% do lote vendido</span><span id=\"im-prox\"></span></div>\n        <div class=\"trilho\" role=\"progressbar\" aria-label=\"Ingressos vendidos do lote atual\" aria-valuemin=\"0\" aria-valuemax=\"100\"><div class=\"enchido\" id=\"im-barra\"></div></div>\n      </div>\n      <ul class=\"lotes\" id=\"lotes\" aria-label=\"Lotes do ingresso\"></ul>\n      <p class=\"incl\">2 noites ao vivo, das 19h às 22h · Grupo da turma com o RedPro</p>\n      <p class=\"incl cert\"><i data-lucide=\"award\"></i>Certificado digital para quem assistir às duas noites</p>\n      <p class=\"obj\">O ingresso sobe a cada lote. Hoje <span data-im=\"preco\">R$ 44</span> te dão duas noites de imersão, com o Hermes rodando no fim, pra você decidir se agente de IA é pra você.</p>\n      <a class=\"btn im-acao\" href=\"#\">Garantir minha vaga por <span data-im=\"preco\">R$ 44</span> <i data-lucide=\"arrow-right\"></i></a>\n      <div class=\"garantia\"><i data-lucide=\"shield-check\"></i><div><b>Garantia de 7 dias</b><span>Pediu o reembolso pela Hotmart em até 7 dias da compra, recebe 100% de volta, sem precisar explicar.</span></div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ FAQ ============ -->\n<section class=\"alt\" id=\"faq\">\n  <div class=\"wrap\">\n    <div class=\"head-c\">\n      <span class=\"kicker rv\">Antes de você perguntar</span>\n      <h2 class=\"rv\">Dúvidas comuns, resolvidas antes de você perguntar</h2>\n    </div>\n    <div class=\"faq rv\">\n      <details><summary>Isso substitui meu Chat GPT ou meu Claude?<i data-lucide=\"plus\"></i></summary><p>O Hermes usa esses modelos como cérebro: você escolhe qual LLM ele aluga pra cada tarefa. Quando você pluga sua IA preferida nele, ele passa a responder exatamente como ela. A diferença é que agora sua IA tem um corpo: as mãos, a memória e as ferramentas.</p></details>\n      <details><summary>Preciso saber programar?<i data-lucide=\"plus\"></i></summary><p>Zero. Você conversa com o Hermes em português, por texto ou por voz.</p></details>\n      <details><summary>Funciona no Windows, Mac ou Linux?<i data-lucide=\"plus\"></i></summary><p>Sim. Funciona em Windows, Mac ou Linux.</p></details>\n      <details><summary>E se eu já tiver Chat GPT ou Claude pago? Preciso pagar de novo?<i data-lucide=\"plus\"></i></summary><p>Não. O Hermes consegue usar a assinatura que você já paga em vários provedores.</p></details>\n      <details><summary>Quando é e quanto tempo dura?<i data-lucide=\"plus\"></i></summary><p>Quarta, 25/11, e quinta, 26/11, das 19h às 22h, no horário de Brasília. São duas noites de três horas, ao vivo.</p></details>\n      <details><summary>E se eu não puder estar ao vivo nas duas noites?<i data-lucide=\"plus\"></i></summary><p>Na hora da compra você pode levar também a gravação das duas noites. Quem está ao vivo tira dúvida na hora e vê o próprio Hermes executar uma tarefa real.</p></details>\n      <details><summary>Preciso ter um servidor antes?<i data-lucide=\"plus\"></i></summary><p>Não. O servidor é o assunto da noite 2: eu mostro o custo real e a gente monta o seu ao vivo.</p></details>\n      <details><summary>É seguro deixar um agente rodando?<i data-lucide=\"plus\"></i></summary><p>Segurança entra nas duas noites. Na primeira você define o que o Hermes pode acessar na sua máquina. Na segunda a gente cuida do servidor: quem consegue falar com ele e o que ele faz sozinho.</p></details>\n      <details><summary>Quanto custa manter o Hermes funcionando?<i data-lucide=\"plus\"></i></summary><p>Na noite 2 eu mostro o número real: servidor mais modelo. E como escolher o que cabe no seu bolso.</p></details>\n      <details><summary>Por que o ingresso muda de preço?<i data-lucide=\"plus\"></i></summary><p>Porque o ingresso é vendido em três lotes, cada um com preço e data próprios. As duas noites são as mesmas em qualquer lote. O que muda é quanto você paga por elas, e paga menos quem decide mais cedo. Quando o lote vira, o preço anterior sai do ar e não volta. <span id=\"faq-lotes\"></span></p></details>\n      <details><summary>Vai ter venda de alguma coisa no final?<i data-lucide=\"plus\"></i></summary><p>Na noite 2 eu apresento a Formação Arquiteto de Agentes, pra quem quiser continuar. Comprar é opcional, e as duas noites valem sozinhas.</p></details>\n      <details><summary>E se eu entrar e não gostar?<i data-lucide=\"plus\"></i></summary><p>Você tem 7 dias de garantia a partir da compra: pediu o reembolso pela Hotmart dentro desse prazo, recebe 100% de volta, sem precisar explicar. E quem fica sai das duas noites com o Hermes rodando, mesmo que decida não seguir depois.</p></details>\n    </div>\n  </div>\n</section>\n\n<!-- ============ FINAL ============ -->\n<footer class=\"final grid-bg\" id=\"final\">\n  <div class=\"wrap\">\n    <span class=\"status rv\"><i></i>SEU HERMES: ONLINE</span>\n    <h2 class=\"rv\">Seu agente está pronto pra instalar. Falta só você.</h2>\n    <p class=\"micro rv\"><span data-im=\"preco\">R$ 44</span> · 2 noites ao vivo · <span data-im=\"noites\">25 e 26/11</span>, às 19h</p>\n    <a class=\"btn im-acao rv\" href=\"#\">Quero minha vaga na Imersão <i data-lucide=\"arrow-right\"></i></a>\n  </div>\n  <div class=\"lower\">\n    <div class=\"wrap\">\n      <div class=\"lt\"><span class=\"bar\"></span><div><b>RedPro</b><span>RedPro AI Academy · @redpro.ia</span></div></div>\n      <div class=\"legal\">\n        <p>Imersão Arquiteto de Agentes · quarta e quinta, 19h às 22h · <span data-im=\"noites\">25 e 26/11</span></p>\n        <p>RedPro AI Academy · CNPJ 59.015.480/0001-07 · <a href=\"mailto:suporte@redpro.com.br\">suporte@redpro.com.br</a></p>\n      </div>\n    </div>\n  </div>\n</footer>\n\n<!-- ============ PRÉ-CHECKOUT ============ -->\n<div class=\"pc\" id=\"pc\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pc-t\" hidden>\n  <div class=\"pc-box\">\n    <button type=\"button\" class=\"pc-x\" id=\"pc-x\" aria-label=\"Fechar\"><i data-lucide=\"x\"></i></button>\n    <span class=\"kicker\">Falta um passo</span>\n    <h3 id=\"pc-t\">Para onde a gente manda o seu acesso?</h3>\n    <p class=\"s\">Preencha e siga para o pagamento seguro na Hotmart. Seus dados já chegam preenchidos lá.</p>\n    <form id=\"pc-f\" novalidate>\n      <label for=\"pc-nome\">Nome</label>\n      <input id=\"pc-nome\" name=\"nome\" autocomplete=\"name\" maxlength=\"120\" required data-clarity-mask=\"true\">\n      <label for=\"pc-email\">E-mail</label>\n      <input id=\"pc-email\" name=\"email\" type=\"email\" inputmode=\"email\" autocomplete=\"email\" maxlength=\"160\" required data-clarity-mask=\"true\">\n      <label for=\"pc-wa\">WhatsApp com DDD</label>\n      <input id=\"pc-wa\" name=\"whatsapp\" type=\"tel\" inputmode=\"tel\" autocomplete=\"tel\" maxlength=\"20\" placeholder=\"(11) 91234-5678\" required data-clarity-mask=\"true\">\n      <p class=\"pc-err\" id=\"pc-err\" role=\"alert\"></p>\n      <button class=\"btn\" type=\"submit\" id=\"pc-ir\">Ir para o pagamento <i data-lucide=\"arrow-right\"></i></button>\n      <p class=\"lgpd\">Ao continuar, você concorda que a RedPro AI Academy use esses dados para falar com você por e-mail e WhatsApp sobre a Imersão, inclusive se a compra não for concluída. Você pode pedir a exclusão a qualquer momento em suporte@redpro.com.br. <a href=\"/privacidade\" target=\"_blank\" rel=\"noopener\">Política de privacidade</a>.</p>\n    </form>\n  </div>\n</div>\n\n<script defer src=\"https://cdn.jsdelivr.net/npm/lucide@0.469.0/dist/umd/lucide.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/ScrollTrigger.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/lenis@1.1.18/dist/lenis.min.js\"></script>\n<script>\n/* Parallax do hero — porte da técnica do componente Osmo (GSAP ScrollTrigger + Lenis).\n   Camada 1 = cena 3D (fundo, mais lenta) · 2 = brilho · 3 = texto · 4 = personagem (frente). */\ndocument.addEventListener('DOMContentLoaded', function(){\n  if (matchMedia('(prefers-reduced-motion: reduce)').matches || !window.gsap || !window.ScrollTrigger) return;\n  gsap.registerPlugin(ScrollTrigger);\n  var hero = document.querySelector('[data-parallax-layers]');\n  if (hero){\n    var tl = gsap.timeline({scrollTrigger:{trigger:hero, start:'0% 0%', end:'100% 0%', scrub:0}});\n    [{l:'1',y:32},{l:'2',y:24},{l:'3',y:12},{l:'4',y:-18}].forEach(function(o,i){\n      tl.to(hero.querySelectorAll('[data-parallax-layer=\"'+o.l+'\"]'), {yPercent:o.y, ease:'none'}, i ? '<' : undefined);\n    });\n    // o texto também some enquanto desce, pra não brigar com a seção seguinte\n    tl.to(hero.querySelector('[data-parallax-layer=\"3\"]'), {opacity:.15, duration:.2, ease:'none'}, .3);\n  }\n  if (window.Lenis){\n    var lenis = new Lenis(); window.IM_LENIS = lenis;\n    lenis.on('scroll', ScrollTrigger.update);\n    gsap.ticker.add(function(t){ lenis.raf(t*1000); });\n    gsap.ticker.lagSmoothing(0);\n    document.querySelectorAll('a[href^=\"#\"]').forEach(function(a){\n      a.addEventListener('click', function(e){ var id = a.getAttribute('href'); if (!id || id.charAt(0) !== '#' || id.length < 2) return; var el = document.querySelector(id); if (!el) return; e.preventDefault(); lenis.scrollTo(el, {offset:-20}); });\n    });\n  }\n  // mouse: personagem e brilho se deslocam em sentidos opostos (profundidade)\n  if (matchMedia('(pointer: fine)').matches && hero){\n    hero.addEventListener('pointermove', function(e){\n      var x = e.clientX/innerWidth*2-1, y = e.clientY/innerHeight*2-1;\n      hero.style.setProperty('--mx', (-x*28).toFixed(1)+'px');\n      hero.style.setProperty('--my', (-y*14).toFixed(1)+'px');\n    });\n  }\n});\n</script>\n<script>\n/* dados vivos + ícones + reveal + dia ativo */\n(function(){\n  var IM = window.IM || {};\n  document.querySelectorAll('[data-im]').forEach(function(el){ var k=el.dataset.im; if(IM[k]) el.textContent=IM[k]; });\n  if (IM.checkout) {\n    var q = new URLSearchParams(location.search), u = IM.checkout, ck = document.cookie.match(/(?:^|; )_fbc=([^;]+)/), fbc = ck ? decodeURIComponent(ck[1]) : '';\n    if (!/^fb\\.\\d+\\.\\d+\\..+/.test(fbc)) fbc = q.get('fbclid') ? 'fb.1.' + Date.now() + '.' + q.get('fbclid') : '';\n    var org = q.get('utm_content') || q.get('utm_campaign'); if (org) { var sck = ('im-A-' + org).replace(/[^A-Za-z0-9_-]/g, '').slice(0, 100); if (sck.length > 5) u += '&sck=' + sck; }\n    if (fbc) u += '&xcod=' + encodeURIComponent(fbc);\n    ['utm_source','utm_medium','utm_campaign','utm_content','utm_term'].forEach(function(k){ if (q.get(k)) u += '&' + k + '=' + encodeURIComponent(q.get(k)); });\n    document.querySelectorAll('a.im-acao').forEach(function(a){ a.href = u; });\n  }\n  var fl = document.getElementById('faq-lotes');\n  if (fl && IM.lotes) fl.textContent = IM.lotes.map(function(l){ return 'Lote '+l.n+': '+l.preco+(l.n===IM.lotes.length?', de '+l.de+' até a noite 1':', de '+l.de+' a '+l.ate); }).join('. ')+'.';\n  var ul = document.getElementById('lotes');\n  if (ul && IM.lotes) IM.lotes.forEach(function(l){ var li = document.createElement('li'); if (IM.lote && l.n === IM.lote.n) li.className = 'on'; li.innerHTML = '<span>Lote '+l.n+' · '+l.de+(l.n===IM.lotes.length?' até a noite 1':' a '+l.ate)+'</span><b>'+l.preco+'</b>'; ul.appendChild(li); });\n  if (ul && IM.lote && IM.lote.n === 4) { var lx = document.createElement('li'); lx.className = 'on'; lx.innerHTML = '<span>Lote extra · até a noite 1</span><b>'+IM.lote.preco+'</b>'; ul.appendChild(lx); }\n  // de/por, lote atual e barra de % vendido (só com contagem real; 0% não aparece)\n  var de = document.getElementById('im-de'); if (de && IM.de) de.hidden = false;\n  var lt = document.getElementById('im-lote-tag'); if (lt && IM.rotulo) { lt.textContent = IM.rotulo + (IM.ate ? ' · até ' + IM.ate : ''); lt.hidden = false; }\n  var esc = document.getElementById('im-escassez'), pct = +IM.vendidoPct;\n  if (esc && IM.vendidoPct != null && pct > 0 && !IM.encerrado) {\n    document.getElementById('im-pct').textContent = pct;\n    if (IM.proximoPreco) document.getElementById('im-prox').textContent = 'depois: ' + IM.proximoPreco;\n    esc.querySelector('.trilho').setAttribute('aria-valuenow', pct);\n    esc.hidden = false;\n    var bar = document.getElementById('im-barra'), io3 = new IntersectionObserver(function(es){ if (es[0].isIntersecting) { bar.style.width = pct + '%'; io3.disconnect(); } });\n    io3.observe(esc);\n  }\n  // Clarity: marca quem chegou na seção de preço\n  var inv = document.getElementById('investimento');\n  if (inv) { var io4 = new IntersectionObserver(function(es){ if (es[0].isIntersecting) { if (typeof window.clarity === 'function') clarity('event', 'viu_preco'); io4.disconnect(); } }, {threshold:.3}); io4.observe(inv); }\n  // pré-checkout: nome, e-mail e WhatsApp antes da Hotmart; grava e segue mesmo se falhar\n  var pc = document.getElementById('pc'), pf = document.getElementById('pc-f'), alvo = '';\n  function abrir(e){\n    var a = e.currentTarget;\n    if (!/^https:\\/\\//.test(a.href) || e.metaKey || e.ctrlKey || e.shiftKey || e.button === 1) return;\n    e.preventDefault(); alvo = a.href; pc.hidden = false; document.documentElement.style.overflow = 'hidden';\n    if (window.IM_LENIS) IM_LENIS.stop();\n    if (typeof window.clarity === 'function') clarity('event', 'abriu_pre_checkout');\n    setTimeout(function(){ document.getElementById('pc-nome').focus(); }, 40);\n  }\n  function fechar(){ pc.hidden = true; document.documentElement.style.overflow = ''; if (window.IM_LENIS) IM_LENIS.start(); }\n  if (pc && pf) {\n    document.querySelectorAll('a.im-acao').forEach(function(a){ a.addEventListener('click', abrir); });\n    document.getElementById('pc-x').addEventListener('click', fechar);\n    pc.addEventListener('click', function(e){ if (e.target === pc) fechar(); });\n    document.addEventListener('keydown', function(e){ if (e.key === 'Escape' && !pc.hidden) fechar(); });\n    pf.addEventListener('submit', function(e){\n      e.preventDefault();\n      var nome = pf.nome.value.trim(), email = pf.email.value.trim().toLowerCase(), wa = pf.whatsapp.value.replace(/\\D/g, ''), err = document.getElementById('pc-err');\n      if (wa.length >= 12 && wa.indexOf('55') === 0) wa = wa.slice(2);\n      if (nome.length < 2) { err.textContent = 'Escreva o seu nome.'; pf.nome.focus(); return; }\n      if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)) { err.textContent = 'Confira o e-mail.'; pf.email.focus(); return; }\n      if (wa.length < 10 || wa.length > 11) { err.textContent = 'Coloque o WhatsApp com DDD, só números.'; pf.whatsapp.focus(); return; }\n      err.textContent = '';\n      var bt = document.getElementById('pc-ir'); bt.disabled = true; bt.textContent = 'Indo para o pagamento...';\n      var dest = alvo + '&name=' + encodeURIComponent(nome) + '&email=' + encodeURIComponent(email) + '&phoneac=' + wa.slice(0, 2) + '&phonenumber=' + wa.slice(2);\n      var qs = new URLSearchParams(location.search), pa = new URL(alvo).searchParams;\n      var corpo = { nome: nome, email: email, whatsapp: wa, consentimento: true, lote: IM.lote ? IM.lote.n : null, oferta: pa.get('off'), sck: pa.get('sck'), src: pa.get('src') };\n      ['utm_source','utm_medium','utm_campaign','utm_content','utm_term'].forEach(function(k){ corpo[k] = qs.get(k); });\n      if (typeof window.clarity === 'function') clarity('event', 'enviou_pre_checkout');\n      var foi = false; function ir(){ if (foi) return; foi = true; location.href = dest; }\n      setTimeout(ir, 2500);\n      try { fetch('/api/imersao-pre-checkout', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(corpo), keepalive: true }).then(ir, ir); } catch (_) { ir(); }\n    });\n  }\n  document.addEventListener('DOMContentLoaded', function(){ if (window.lucide) lucide.createIcons({attrs:{'stroke-width':1.7}}); });\n  var io = new IntersectionObserver(function(es){ es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target);} }); },{threshold:.12,rootMargin:'0px 0px -6% 0px'});\n  document.querySelectorAll('.rv').forEach(function(el,i){ el.style.transitionDelay = (Math.min(i%4,3)*70)+'ms'; io.observe(el); });\n  window.IM_DIA = 0;\n  var days = document.querySelectorAll('.day');\n  var io2 = new IntersectionObserver(function(es){ es.forEach(function(e){ if(e.isIntersecting){ days.forEach(function(d){d.classList.remove('on')}); e.target.classList.add('on'); window.IM_DIA = +e.target.dataset.i; } }); },{rootMargin:'-45% 0px -45% 0px'});\n  days.forEach(function(d){ io2.observe(d); });\n  days[0] && days[0].classList.add('on');\n})();\n</script>\n\n<script type=\"module\">\n/* three.js só depois do load/idle: não disputa banda com o pixel nem com o herói */\nasync function bootHero3d(){\nconst THREE = await import('three');\nconst { RoundedBoxGeometry } = await import('three/addons/geometries/RoundedBoxGeometry.js');\nconst { RoomEnvironment } = await import('three/addons/environments/RoomEnvironment.js');\n\nconst REDUZ = matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst BLUE = new THREE.Color('#4458FF');\nconst BLUE_HI = new THREE.Color('#6E7DFF');\n\nfunction makeRenderer(canvas){\n  const r = new THREE.WebGLRenderer({canvas, antialias:true, alpha:true, powerPreference:'high-performance'});\n  r.setPixelRatio(Math.min(devicePixelRatio, 2));\n  r.toneMapping = THREE.ACESFilmicToneMapping;\n  r.toneMappingExposure = 1.0;\n  r.outputColorSpace = THREE.SRGBColorSpace;\n  return r;\n}\nfunction envFor(renderer){\n  const pm = new THREE.PMREMGenerator(renderer);\n  const env = pm.fromScene(new RoomEnvironment(), 0.04).texture;\n  pm.dispose();\n  return env;\n}\nfunction dotTexture(){\n  const c = document.createElement('canvas'); c.width = c.height = 64;\n  const g = c.getContext('2d'); const gr = g.createRadialGradient(32,32,0,32,32,32);\n  gr.addColorStop(0,'rgba(255,255,255,1)'); gr.addColorStop(.25,'rgba(255,255,255,.85)'); gr.addColorStop(1,'rgba(255,255,255,0)');\n  g.fillStyle = gr; g.fillRect(0,0,64,64);\n  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;\n}\n/* só anima quando visível */\nfunction runWhenVisible(el, tick){\n  let on = false, raf = 0;\n  const loop = (t) => { tick(t); raf = requestAnimationFrame(loop); };\n  new IntersectionObserver(([e]) => {\n    if (e.isIntersecting && !on){ on = true; raf = requestAnimationFrame(loop); }\n    else if (!e.isIntersecting && on){ on = false; cancelAnimationFrame(raf); }\n  }).observe(el);\n}\n\n/* =================== HERO: terminal vivo =================== */\n(function hero(){\n  const canvas = document.getElementById('hero3d');\n  let renderer; try { renderer = makeRenderer(canvas); } catch(e){ return; }\n  const scene = new THREE.Scene();\n  scene.environment = envFor(renderer);\n  scene.fog = new THREE.Fog(0x0A0A0A, 7, 19);\n  const camera = new THREE.PerspectiveCamera(34, 1, 0.1, 60);\n  camera.position.set(0, 0.35, 8);\n\n  /* ---- tela do terminal (canvas → textura) ---- */\n  const TW = 1280, TH = 800;\n  const tc = document.createElement('canvas'); tc.width = TW; tc.height = TH;\n  const g = tc.getContext('2d');\n  const screenTex = new THREE.CanvasTexture(tc);\n  screenTex.colorSpace = THREE.SRGBColorSpace; screenTex.anisotropy = 8;\n  const L = [\n    ['$','hermes gateway status'],\n    ['●','ready · vps · telegram · whatsapp'],\n    ['$','hermes cron list'],\n    ['✓','07:00  morning-brief'],\n    ['✓','09:00  relatório-diário'],\n    ['$','hermes browse site-sem-api'],\n    ['→','404 · tentando outro caminho'],\n    ['✓','dados coletados e salvos'],\n  ];\n  const COL = {'$':'#6E7DFF','●':'#6E7DFF','→':'#77777c','✓':'#F5F5F5'};\n  let typed = 130, lastDraw = 0, blink = true;\n  const total = L.reduce((s,l)=>s+l[1].length+2, 0);\n  function drawScreen(){\n    g.fillStyle = '#07080B'; g.fillRect(0,0,TW,TH);\n    // leve vinheta azul\n    const vg = g.createRadialGradient(TW*.3,TH*.2,50,TW*.5,TH*.5,TW*.8);\n    vg.addColorStop(0,'rgba(68,88,255,.10)'); vg.addColorStop(1,'rgba(0,0,0,0)');\n    g.fillStyle = vg; g.fillRect(0,0,TW,TH);\n    // barra de título\n    g.fillStyle = '#0E1014'; g.fillRect(0,0,TW,64);\n    g.fillStyle = 'rgba(255,255,255,.07)'; g.fillRect(0,64,TW,2);\n    ['#3a3a40','#3a3a40','#3a3a40'].forEach((c,i)=>{ g.fillStyle=c; g.beginPath(); g.arc(40+i*30,32,8,0,7); g.fill(); });\n    g.font = '500 22px \"JetBrains Mono\", monospace'; g.fillStyle = '#6a6a70'; g.textAlign = 'center';\n    g.fillText('alfred@hermes — gateway', TW/2, 40); g.textAlign = 'left';\n    g.fillStyle = '#6E7DFF'; g.beginPath(); g.arc(TW-44,32,6,0,7); g.fill();\n    // linhas\n    g.font = '500 36px \"JetBrains Mono\", monospace';\n    let left = typed, y = 134; const lh = 58;\n    for (const [p, txt] of L){\n      if (left <= 0) break;\n      const n = Math.min(txt.length, left - 2); left -= txt.length + 2;\n      g.fillStyle = COL[p]; g.fillText(p, 52, y);\n      g.fillStyle = p==='$' ? '#F5F5F5' : (p==='→' ? '#8A8A8A' : '#D8D8DC');\n      const s = txt.slice(0, Math.max(0,n)); g.fillText(s, 100, y);\n      if (left <= 0 && blink){ const w = g.measureText(s).width; g.fillStyle = '#6E7DFF'; g.fillRect(104+w, y-30, 18, 36); }\n      y += lh;\n    }\n    if (typed >= total && blink){ g.fillStyle = '#6E7DFF'; g.fillText('$', 52, y); g.fillRect(100, y-30, 18, 36); }\n    // scanlines sutis\n    g.fillStyle = 'rgba(255,255,255,.018)'; for (let s=66; s<TH; s+=4) g.fillRect(0,s,TW,1);\n    screenTex.needsUpdate = true;\n  }\n\n  /* ---- corpo do terminal ---- */\n  const term = new THREE.Group(); scene.add(term);\n  const W = 3.3, H = 2.12, D = 0.26;\n  const metal = new THREE.MeshPhysicalMaterial({color:0x2a2d35, metalness:0.95, roughness:0.22, clearcoat:0.8, clearcoatRoughness:0.15, envMapIntensity:1.8});\n  const body = new THREE.Mesh(new RoundedBoxGeometry(W, H, D, 8, 0.09), metal); term.add(body);\n  const screen = new THREE.Mesh(new THREE.PlaneGeometry(W-0.16, H-0.16), new THREE.MeshBasicMaterial({map:screenTex, toneMapped:false}));\n  screen.position.z = D/2 + 0.002; term.add(screen);\n  // vidro por cima da tela: reflexo frio\n  const glass = new THREE.Mesh(new THREE.PlaneGeometry(W-0.16, H-0.16), new THREE.MeshPhysicalMaterial({color:0xffffff, metalness:0, roughness:0.05, transmission:0, transparent:true, opacity:0.06, envMapIntensity:2}));\n  glass.position.z = D/2 + 0.006; term.add(glass);\n  // aro azul fino (acento)\n  const rimGeo = new THREE.EdgesGeometry(new THREE.PlaneGeometry(W-0.12, H-0.12));\n  const rim = new THREE.LineSegments(rimGeo, new THREE.LineBasicMaterial({color:BLUE_HI, transparent:true, opacity:.55}));\n  rim.position.z = D/2 + 0.004; term.add(rim);\n  // brilho atrás\n  const halo = new THREE.Sprite(new THREE.SpriteMaterial({map:dotTexture(), color:BLUE, transparent:true, opacity:.35, blending:THREE.AdditiveBlending, depthWrite:false}));\n  halo.scale.set(9,6,1); halo.position.z = -0.6; term.add(halo);\n\n  /* ---- chão de grade + trilhas de circuito ---- */\n  const floorY = -2.0;\n  const gridMat = new THREE.LineBasicMaterial({color:0xffffff, transparent:true, opacity:.07});\n  const gp = [];\n  for (let i=-24;i<=24;i++){ gp.push(i*.6,floorY,-18, i*.6,floorY,6); }\n  for (let j=-30;j<=10;j++){ gp.push(-14.4,floorY,j*.6, 14.4,floorY,j*.6); }\n  const gg = new THREE.BufferGeometry(); gg.setAttribute('position', new THREE.Float32BufferAttribute(gp,3));\n  scene.add(new THREE.LineSegments(gg, gridMat));\n\n  // trilhas em ângulo reto saindo da base do terminal (código/circuito)\n  const traces = [], pulses = [];\n  const traceMat = new THREE.LineBasicMaterial({color:0x9aa4ff, transparent:true, opacity:.22});\n  const pulseTex = dotTexture();\n  const rnd = (a,b)=>a+Math.random()*(b-a);\n  const snap = v => Math.round(v/.6)*.6;\n  for (let k=0;k<14;k++){\n    const pts = [new THREE.Vector3(snap(rnd(-1.2,1.2)), floorY+.002, 0)];\n    let p = pts[0].clone(), dir = Math.random()<.5 ? 'x':'z';\n    for (let s=0;s<4;s++){\n      const q = p.clone();\n      if (dir==='x') q.x += (Math.random()<.5?-1:1)*.6*Math.ceil(rnd(2,7)); else q.z += (Math.random()<.35?1:-1)*.6*Math.ceil(rnd(2,8));\n      pts.push(q); p = q; dir = dir==='x'?'z':'x';\n    }\n    const geo = new THREE.BufferGeometry().setFromPoints(pts);\n    scene.add(new THREE.Line(geo, traceMat));\n    const lens = []; let tot = 0; for (let i=1;i<pts.length;i++){ const l = pts[i].distanceTo(pts[i-1]); lens.push(l); tot += l; }\n    traces.push({pts, lens, tot});\n    const sp = new THREE.Sprite(new THREE.SpriteMaterial({map:pulseTex, color:BLUE_HI, transparent:true, blending:THREE.AdditiveBlending, depthWrite:false}));\n    sp.scale.setScalar(.22); scene.add(sp);\n    pulses.push({sp, tr:traces[k], t:Math.random(), v:rnd(.05,.12)});\n  }\n  function along(tr, t){\n    let d = t*tr.tot;\n    for (let i=0;i<tr.lens.length;i++){ if (d <= tr.lens[i]) return tr.pts[i].clone().lerp(tr.pts[i+1], d/tr.lens[i]); d -= tr.lens[i]; }\n    return tr.pts[tr.pts.length-1].clone();\n  }\n  // \"cabo\" de luz da base do terminal até o chão\n  const cableGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,-H/2,0), new THREE.Vector3(0,floorY,0)]);\n  const cable = new THREE.Line(cableGeo, new THREE.LineBasicMaterial({color:BLUE_HI, transparent:true, opacity:.35}));\n  scene.add(cable);\n\n  /* ---- partículas subindo (bits de dado) ---- */\n  const N = 520, pos = new Float32Array(N*3), spd = new Float32Array(N);\n  for (let i=0;i<N;i++){ pos[i*3]=rnd(-9,9); pos[i*3+1]=rnd(floorY,5); pos[i*3+2]=rnd(-10,1.2); spd[i]=rnd(.08,.35); }\n  const pg = new THREE.BufferGeometry(); pg.setAttribute('position', new THREE.BufferAttribute(pos,3));\n  const pm = new THREE.PointsMaterial({map:dotTexture(), color:BLUE_HI, size:.045, transparent:true, opacity:.85, blending:THREE.AdditiveBlending, depthWrite:false, sizeAttenuation:true});\n  const parts = new THREE.Points(pg, pm); scene.add(parts);\n\n  /* ---- luzes ---- */\n  scene.add(new THREE.AmbientLight(0xffffff, .15));\n  const key = new THREE.DirectionalLight(0xdfe6ff, 1.6); key.position.set(-4,5,6); scene.add(key);\n  const rimL = new THREE.PointLight(BLUE, 30, 12); rimL.position.set(2.5,1,-2); scene.add(rimL);\n\n  /* ---- layout responsivo ---- */\n  let mobile = false, baseX = 0, baseY = 0;\n  function resize(){\n    const w = canvas.clientWidth, h = canvas.clientHeight;\n    renderer.setSize(w, h, false); camera.aspect = w/h; camera.updateProjectionMatrix();\n    mobile = w < 900;\n    const vh = 2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*camera.position.z, vw = vh*camera.aspect;\n    if (mobile){ term.scale.setScalar(vw*.14); baseX = -vw*.255; baseY = vh*.255; }\n    else { baseX = Math.min(vw*.17, 2.35); baseY = .3; term.scale.setScalar(w<1200 ? .7 : .78); }\n    term.position.set(baseX, baseY, 0);\n    cable.position.x = baseX;\n  }\n  addEventListener('resize', resize); resize();\n\n  let mx = 0, my = 0;\n  addEventListener('pointermove', e => { mx = e.clientX/innerWidth*2-1; my = e.clientY/innerHeight*2-1; });\n\n  const clock = new THREE.Clock();\n  drawScreen();\n  runWhenVisible(canvas, () => {\n    const dt = Math.min(clock.getDelta(), .05), t = clock.elapsedTime;\n    // digitação\n    if (!REDUZ){\n      if (t - lastDraw > .045){\n        lastDraw = t;\n        if (typed < total) typed += 1 + (Math.random()<.3 ? 1 : 0);\n        else if (t % 7 < .05) typed = 60;\n        if (Math.floor(t*2)%2 !== +blink){ blink = !blink; }\n        drawScreen();\n      }\n    } else if (typed < total){ typed = total; drawScreen(); }\n    // rolagem: 0 no topo, 1 quando o hero sai da tela\n    const sp = REDUZ ? 0 : Math.min(1, Math.max(0, scrollY / (canvas.clientHeight || 1)));\n    // terminal flutua, sobe e inclina com a rolagem, olha pro cursor\n    const bob = REDUZ ? 0 : Math.sin(t*.9)*.08;\n    term.position.y = baseY + bob + sp*.7;\n    term.position.x = baseX;\n    term.position.z = sp*.8;\n    term.rotation.y += ((mobile ? .26 : .32) + mx*.34 - sp*.25 - term.rotation.y)*.07;\n    term.rotation.x += (-.04 + my*.2 + sp*.22 - term.rotation.x)*.07;\n    halo.material.opacity = .28 + Math.sin(t*1.7)*.06;\n    // pulsos nas trilhas\n    for (const p of pulses){ p.t = (p.t + p.v*dt*(REDUZ?0:1)) % 1; p.sp.position.copy(along(p.tr, p.t)); p.sp.position.x += 0; p.sp.material.opacity = Math.sin(p.t*Math.PI); }\n    // partículas\n    if (!REDUZ){\n      const a = pg.attributes.position.array;\n      const boost = 1 + sp*5;\n      for (let i=0;i<N;i++){ a[i*3+1] += spd[i]*dt*boost; if (a[i*3+1] > 5){ a[i*3+1] = floorY; } }\n      pg.attributes.position.needsUpdate = true;\n      pm.opacity = .7 + Math.sin(t*3)*.15;\n    }\n    camera.position.x += (mx*.9 - camera.position.x)*.05;\n    camera.position.y += (.35 - my*.45 + sp*.5 - camera.position.y)*.05;\n    camera.position.z = 8 + sp*1.6;\n    camera.lookAt(0, sp*.4, 0);\n    renderer.render(scene, camera);\n  });\n  document.fonts && document.fonts.ready.then(drawScreen);\n})();\n}\n(function(){\n  var iniciou = false;\n  function ir(){ if (iniciou) return; iniciou = true; bootHero3d(); }\n  function idle(){ if ('requestIdleCallback' in window) requestIdleCallback(ir, {timeout: 2500}); else setTimeout(ir, 1200); }\n  if (document.readyState === 'complete') idle(); else addEventListener('load', idle, {once: true});\n})();\n</script>\n<script>\n/* Mapa da semana — porte do componente WorksWheel (React) pra JS puro.\n   Tudo é um número, `turn`: 0 = anel, 1 = tambor com Segunda na frente, e cada\n   inteiro depois disso é um dia a mais girado. Uma passada de rAF escreve os\n   transforms direto no DOM. Geometria e constantes idênticas ao original. */\n(function(){\n  var root = document.getElementById('ww'); if (!root) return;\n  if (matchMedia('(max-width:900px),(pointer:coarse)').matches) return;\n  var stage = root.querySelector('.ww-stage'), wheel = root.querySelector('.ww-wheel');\n  var cards = [].slice.call(root.querySelectorAll('.ww-card'));\n  var label = root.querySelector('.ww-label'), title = root.querySelector('.ww-title');\n  var btns = [].slice.call(root.querySelectorAll('.ww-index button'));\n  var hint = root.querySelector('.ww-hint');\n  var CARD_H=.38, CARD_MAX_W=.34, CARD_RATIO=1.45, STEP=40, DRUM=2.22, LENS=2.7, RING_R=1.14, BOW=1.82, TITLE=.124, INDEX=.04, CULL=1.6;\n  var WHEEL_UNITS=420, DRAG_UNITS=420, SETTLE=140, EASE=.12;\n  var REDUZ = matchMedia('(prefers-reduced-motion: reduce)').matches;\n  var count = cards.length, last = count-1, turn = 0, target = 0, active = -1, M = null;\n  var clamp = function(v,a,b){ return Math.min(b, Math.max(a, v)); };\n  var rad = function(d){ return d*Math.PI/180; };\n  function measure(){\n    var w = stage.clientWidth, h = stage.clientHeight;\n    var cardW = Math.min(h*CARD_H*CARD_RATIO, w*CARD_MAX_W), cardH = cardW/CARD_RATIO, ringR = cardH*RING_R;\n    M = { cardW:cardW, cardH:cardH, ringR:ringR, drumR:cardH*DRUM, bow:cardH*BOW,\n          ringScale: clamp(((2*Math.PI*ringR)/count*.82)/(cardW||1), .16, 1) };\n    stage.style.perspective = (cardH*LENS)+'px';\n    root.style.setProperty('--ch', cardH+'px');\n    cards.forEach(function(c){ c.style.width = cardW+'px'; c.style.height = cardH+'px'; c.style.marginLeft = (-cardW/2)+'px'; c.style.marginTop = (-cardH/2)+'px'; });\n    label.style.fontSize = title.style.fontSize = (cardH*TITLE*1.35)+'px';\n    root.querySelector('.ww-index').style.fontSize = Math.max(13, cardH*INDEX*1.3)+'px';\n  }\n  function place(ringDeg, drumDeg, m){\n    return 'translateX('+(m*-M.bow*(1-Math.cos(rad(drumDeg))))+'px)'\n      + ' rotateZ('+((1-m)*ringDeg)+'deg) translateY('+(-(1-m)*M.ringR)+'px)'\n      + ' rotateX('+(m*drumDeg)+'deg) translateZ('+(m*M.drumR)+'px)';\n  }\n  function setActive(n){\n    if (n === active) return; active = n;\n    cards.forEach(function(c,i){ c.classList.toggle('on', i === n); c.setAttribute('aria-selected', i === n); });\n    btns.forEach(function(b,i){ b.classList.toggle('on', i === n); });\n    title.textContent = btns[n] ? btns[n].textContent : '';\n    stage.setAttribute('aria-activedescendant', 'ww-'+n);\n  }\n  function draw(){\n    var gap = target - turn;\n    if (Math.abs(gap) < .0005) turn = target; else turn += gap*(REDUZ ? 1 : EASE);\n    var m = clamp(turn, 0, 1), pos = Math.max(0, turn-1);\n    wheel.style.transform = 'translateZ('+(-m*M.drumR)+'px)';\n    for (var i=0;i<count;i++){\n      var d = i - pos, c = cards[i];\n      c.style.transform = place(d*(360/count), d*STEP, m);\n      c.style.opacity = (m > .5 && Math.abs(d) > CULL) ? '0' : '1';\n      c.style.zIndex = String(Math.round(100 - Math.abs(d)*2));\n      c.firstElementChild.style.transform = 'scale('+(M.ringScale + (1-M.ringScale)*m)+')';\n    }\n    label.style.opacity = String(1-m);\n    title.style.opacity = String(m);\n    if (hint) hint.style.opacity = String(pos >= last - .05 ? 0 : 1);\n    setActive(clamp(Math.round(pos), 0, last));\n  }\n  var to = function(n){ target = clamp(n, 0, last+1); };\n  // só roda o loop quando a seção está na tela\n  var on = false, raf = 0;\n  function loop(){ draw(); raf = requestAnimationFrame(loop); }\n  new IntersectionObserver(function(es){ var v = es[0].isIntersecting;\n    if (v && !on){ on = true; raf = requestAnimationFrame(loop); } else if (!v && on){ on = false; cancelAnimationFrame(raf); }\n  }).observe(root);\n  measure(); new ResizeObserver(measure).observe(stage); draw();\n  // roda do mouse: só prende a página enquanto ainda tem dia pra girar\n  var settling = 0;\n  var alinhando = 0;\n  stage.addEventListener('wheel', function(e){\n    var next = target + e.deltaY/WHEEL_UNITS;\n    var prende = next > 0 && next < last+1;\n    if (!prende) return;                       // nas pontas, a página segue rolando\n    e.preventDefault();\n    // a seção encaixa na tela antes de começar a girar\n    var r = root.getBoundingClientRect(), topo = Math.max(16, (innerHeight - r.height)/2);\n    if (Math.abs(r.top - topo) > 40){\n      if (Date.now() - alinhando > 700){\n        alinhando = Date.now();\n        var y = scrollY + r.top - topo;\n        if (window.IM_LENIS) IM_LENIS.scrollTo(y, {duration:.7}); else scrollTo({top:y, behavior:'smooth'});\n      }\n      return;\n    }\n    to(next);\n    clearTimeout(settling); settling = setTimeout(function(){ to(Math.round(target)); }, SETTLE);\n  }, {passive:false});\n  var drag = null;\n  stage.addEventListener('pointerdown', function(e){ drag = e.clientY; stage.setPointerCapture(e.pointerId); });\n  stage.addEventListener('pointermove', function(e){ if (drag === null) return; to(target + (drag - e.clientY)/DRAG_UNITS); drag = e.clientY; });\n  stage.addEventListener('pointerup', function(){ drag = null; if (target > 1) to(Math.round(target)); });\n  stage.addEventListener('keydown', function(e){\n    if (e.key === 'ArrowDown') to(Math.round(target)+1); else if (e.key === 'ArrowUp') to(Math.round(target)-1); else return;\n    e.preventDefault();\n  });\n  btns.forEach(function(b,i){ b.addEventListener('click', function(){ to(i+1); }); });\n  window.IM_WHEEL = { to: to, get turn(){ return turn; } };\n})();\n</script>\n<script>__PIXEL_VARIANTE__</script>\n</body>\n</html>\n";
